\section*{প্রশ্ন পরামর্স গুরুত্বপূর্ণ ড্রামিক পলিমন করে। পিপুরসে কেন্ট এনজাইম বাকে না। পিপুরসে অব্যাহত পিভলবণ, যেমন- সোডিয়াম গ্লাইকোকোলেট (sodium glycocholate) ও সোডিয়াম টুরোকোলেট (sodium taurocholate) স্লেই জাতীয় খাদ্যকে ভেঙে ক্ষুদ্র ক্ষুদ্র কণায় পরিণত করে। এ প্রক্রিয়াকে অব্দ্রবণ বা ইমালসিফিকেশন (emulsification) বলে।

অগ্ন্যাশয় রন্দে প্লেজাতীয় খাদ্য পরিপাককারী এনজাইম স্লেহকণা পরিপাকে নিম্নোক্তভাবে ক্রিয়াশীল হয়।

\begin{enumerate}
    \item লাইপেজ নামের এনজাইম স্লেহকণাকে ফ্যাটি এসিড ও গ্লিসারলে রূপান্তরিত করে।
    \begin{equation}
    \text{লাইপেজ} \rightarrow \text{ফ্যাটি এসিড} + \text{গ্লিসারল}
    \end{equation}
    \item ফসফোলাইপেজ এনজাইম ফসফোলিপিডকে ফ্যাটি এসিড, গ্লিসারল ও ফসফোরিক এসিডে পরিণত করে।
    \begin{equation}
    \text{ফসফোলাইপেজ} \rightarrow \text{ফ্যাটি এসিড} + \text{গ্লিসারল} + \text{ফসফোরিক এসিড}
    \end{equation}
    \item কোলেস্টেরল এস্টারেজ এনজাইম কোলেস্টেরল এস্টারের উপর ক্রিয়াশীল হয়ে ফ্যাটি এসিড ও কোলেস্টেরল উৎপন্ন করে।
    \begin{equation}
    \text{কোলেস্টেরল এস্টার} \rightarrow \text{ফ্যাটি এসিড} + \text{কোলেস্টেরল}
    \end{equation}
\end{enumerate}

অক্রিক রন্দে নিম্লিখিত স্লেহ পরিপাককারী এনজাইম ক্রিয়াশীল হয়।

\begin{enumerate}
    \item লাইপেজ এনজাইম পিভলবণের প্রভাবে স্লেহকণায় পরিণত হওয়া লিপিডকে অর্দ্রবিশৃষ্ট করে মনোগ্লিসারাইড ও ফ্যাটি এসিড উৎপন্ন করে। পরে তা ফ্যাটি এসিড ও গ্লিসারলে রূপান্তরিত হয়।
    \begin{equation}
    \text{স্লেহকণা} \rightarrow \text{মনোগ্লিসারাইড} + \text{ফ্যাটি এসিড}
    \end{equation}
    \item লেসিথিনেজ এনজাইম লেসিথিনকে ফ্যাটি এসিড, গ্লিসারল, ফসফোরিক এসিড ও কোলিনে পরিণত করে।
    \begin{equation}
    \text{লেসিথিন} \rightarrow \text{ফ্যাটি এসিড} + \text{গ্লিসারল} + \text{ফসফোরিক এসিড} + \text{কোলিন}
    \end{equation}
\end{enumerate}

